WITH metrics AS (SELECT *, FIRST_VALUE(brand) IGNORE NULLS OVER (PARTITION BY supplier_id ORDER BY launch_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_brand, LAG(cost, 1, 0) OVER (PARTITION BY brand ORDER BY cost, id) AS prev_cost FROM products) SELECT brand, DATE_TRUNC('WEEK', launch_date) AS week_start, AVG(price) FILTER (WHERE brand = 'Stark') AS stark_avg_price, ROUND(AVG(stock_qty), 2) AS avg_stock_qty FROM metrics GROUP BY ROLLUP (brand, DATE_TRUNC('WEEK', launch_date)) ORDER BY week_start NULLS LAST;
